<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { inventoryApi } from '@/api/business'
const route=useRoute()
const tab=ref(String(route.query.tab||'stocks')),loading=ref(false),materials=ref<any[]>([]),suppliers=ref<any[]>([]),stocks=ref<any[]>([]),purchases=ref<any[]>([]),issues=ref<any[]>([]),txns=ref<any[]>([]),summary=reactive({materialCount:0,stockValue:0,lowStockCount:0,expiryAlertCount:0})
const materialVisible=ref(false),materialEditingId=ref<number|null>(null),purchaseVisible=ref(false),receiptVisible=ref(false),receiptPurchaseId=ref<number|null>(null),issueVisible=ref(false),queryVisible=ref(false),txnQueryVisible=ref(false)
const query=reactive({keyword:'',batchNo:'',warehouse:'',location:'',alertStatus:''})
const appliedQuery=ref({...query})
const txnQuery=reactive({keyword:'',bizType:'',batchNo:'',direction:''})
const appliedTxnQuery=ref({...txnQuery})
const material=reactive({code:'',name:'',category:'试剂',specification:'',baseUnit:'瓶',hazardType:'NORMAL',minStock:0,status:'ENABLED',version:0})
const purchase=reactive({materialId:null as number|null,quantity:1,expectedDate:'',purpose:''})
const receipt=reactive({materialId:null as number|null,supplierId:null as number|null,batchNo:'',warehouse:'主仓库',location:'',quantity:1,unitCost:0,productionDate:'',expiryDate:'',bizNo:'',purpose:'验收入库'})
const issue=reactive({batchId:null as number|null,quantity:1,bizNo:'',purpose:''})
const selectedIssueStock=computed(()=>stocks.value.find((row:any)=>row.batchId===issue.batchId))
function validateIssueQuantity(showMessage=true){const available=Number(selectedIssueStock.value?.quantity??0);if(!issue.batchId)return true;if(Number(issue.quantity)>available){if(showMessage)ElMessage.warning(`申请出库数量不能大于当前库存 ${available} ${selectedIssueStock.value?.unit||''}`);return false}return true}
function onIssueQuantityChange(){validateIssueQuantity()}
async function load(){loading.value=true;try{Object.assign(summary,await inventoryApi.summary());[materials.value,suppliers.value,stocks.value,purchases.value,issues.value,txns.value]=await Promise.all([inventoryApi.materials(),inventoryApi.suppliers(),inventoryApi.stocks(),inventoryApi.purchases(),inventoryApi.issues(),inventoryApi.txns()])}finally{loading.value=false}}
function newMaterial(){materialEditingId.value=null;Object.assign(material,{code:'',name:'',category:'试剂',specification:'',baseUnit:'瓶',hazardType:'NORMAL',minStock:0,status:'ENABLED',version:0});materialVisible.value=true}
function editMaterial(row:any){materialEditingId.value=row.id;Object.assign(material,{code:row.code,name:row.name,category:row.category,specification:row.specification||'',baseUnit:row.baseUnit,hazardType:row.hazardType,minStock:Number(row.minStock),status:row.status,version:row.version});materialVisible.value=true}
async function saveMaterial(){if(materialEditingId.value)await inventoryApi.updateMaterial(materialEditingId.value,material);else await inventoryApi.createMaterial(material);materialVisible.value=false;ElMessage.success(materialEditingId.value?'物料档案已修改':'物料档案已新增');await load()}
async function removeMaterial(row:any){try{await ElMessageBox.confirm(`确定删除物料“${row.name}”吗？`,'删除物料',{type:'warning'});await inventoryApi.deleteMaterial(row.id);ElMessage.success('物料档案已删除');await load()}catch(error:any){if(error==='cancel'||error==='close')return;if(error?.response?.data?.message)ElMessage.error(error.response.data.message)}}
async function savePurchase(){await inventoryApi.createPurchase(purchase);purchaseVisible.value=false;ElMessage.success('采购申请已创建');await load()}
async function submit(row:any){await inventoryApi.submitPurchase(row.id);ElMessage.success('已提交审批');await load()}
async function removePurchase(row:any){try{await ElMessageBox.confirm(`确定删除采购申请“${row.requestNo}”吗？删除后不可恢复。`,'删除采购申请',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'});await inventoryApi.deletePurchase(row.id);ElMessage.success('采购申请已删除');await load()}catch(error:any){if(error==='cancel'||error==='close')return;ElMessage.error(error?.response?.data?.message||'删除采购申请失败')}}
async function review(row:any,approved:boolean){await inventoryApi.reviewPurchase(row.id,{approved,comment:approved?'同意采购':'退回修改'});ElMessage.success(approved?'采购申请已通过':'采购申请已退回草稿');await load()}
function openPurchaseReceipt(row:any){receiptPurchaseId.value=row.id;Object.assign(receipt,{materialId:row.materialId,supplierId:row.receiptSupplierId||null,batchNo:row.receiptBatchNo||'',warehouse:row.receiptWarehouse||'主仓库',location:row.receiptLocation||'',quantity:Number(row.receiptQuantity??row.quantity),unitCost:Number(row.receiptUnitCost??0),productionDate:row.receiptProductionDate||'',expiryDate:row.receiptExpiryDate||'',bizNo:row.requestNo,purpose:row.receiptPurpose||row.purpose||'验收入库'});receiptVisible.value=true}
async function saveReceipt(){if(!receiptPurchaseId.value)return;await inventoryApi.submitPurchaseReceipt(receiptPurchaseId.value,{supplierId:receipt.supplierId,batchNo:receipt.batchNo,warehouse:receipt.warehouse,location:receipt.location,quantity:receipt.quantity,unitCost:receipt.unitCost,productionDate:receipt.productionDate||null,expiryDate:receipt.expiryDate||null,purpose:receipt.purpose});receiptVisible.value=false;ElMessage.success('验收入库申请已提交审核');await load()}
async function reviewReceipt(row:any,approved:boolean){await inventoryApi.reviewPurchaseReceipt(row.id,{approved,comment:approved?'验收入库审核通过':'退回重新验收入库'});ElMessage.success(approved?'验收入库已通过，库存已更新':'已退回验收入库');await load()}
async function saveIssue(){if(!validateIssueQuantity())return;await inventoryApi.createIssue(issue);issueVisible.value=false;Object.assign(issue,{batchId:null,quantity:1,bizNo:'',purpose:''});ElMessage.success('出库申请已创建');await load()}
async function submitIssue(row:any){await inventoryApi.submitIssue(row.id);ElMessage.success('出库申请已提交');await load()}
async function removeIssue(row:any){try{await ElMessageBox.confirm(`确定删除出库申请“${row.requestNo}”吗？删除后不可恢复。`,'删除出库申请',{type:'warning'});await inventoryApi.deleteIssue(row.id);ElMessage.success('出库申请已删除');await load()}catch(error:any){if(error==='cancel'||error==='close')return;ElMessage.error(error?.response?.data?.message||'删除出库申请失败')}}
async function reviewIssue(row:any,approved:boolean){if(approved){const stock=stocks.value.find((item:any)=>item.batchId===row.batchId);if(!stock||Number(stock.quantity)<=0){ElMessage.warning('库存已经没有，不能再出库');return}}try{await inventoryApi.reviewIssue(row.id,{approved,comment:approved?'同意出库':'退回修改'});ElMessage.success(approved?'出库申请已通过，库存已扣除':'出库申请已退回');await load()}catch(error:any){ElMessage.error(error?.response?.data?.message||error?.response?.data?.detail||'出库申请审核失败');await load()}}
const alertName=(s:string)=>({NORMAL:'正常',LOW:'低库存',OUT_OF_STOCK:'无库存',EXPIRING:'临期',EXPIRED:'已过期'} as any)[s]||s
const hazardName=(s:string)=>({NORMAL:'普通',HAZARDOUS:'危化品',PRECURSOR:'易制毒',EXPLOSIVE:'易制爆'} as Record<string,string>)[s]||s
const purchaseStatusName=(s:string)=>({DRAFT:'草稿',SUBMITTED:'待审批',APPROVED:'已通过',RECEIPT_REVIEW:'待入库审核',RECEIVED:'已入库',REJECTED:'已退回'} as Record<string,string>)[s]||s
const purchaseStatusType=(s:string)=>({DRAFT:'info',SUBMITTED:'warning',APPROVED:'success',RECEIPT_REVIEW:'warning',RECEIVED:'success',REJECTED:'danger'} as Record<string,string>)[s]||'info'
const issueStatusName=(s:string)=>({DRAFT:'草稿',SUBMITTED:'待审核',ISSUED:'已出库'} as Record<string,string>)[s]||'未知状态'
const issueStatusType=(s:string)=>({DRAFT:'info',SUBMITTED:'warning',ISSUED:'success'} as Record<string,string>)[s]||'info'
const bizTypeName=(s:string)=>({RECEIPT:'验收入库',ISSUE:'领用出库',RETURN:'退库',TRANSFER:'调拨',STOCKTAKE:'盘点调整',DISPOSAL:'报损处置'} as Record<string,string>)[s]||s
const directionName=(s:string)=>({IN:'入库',OUT:'出库'} as Record<string,string>)[s]||s
const stockRowClassName=({row}:{row:any})=>row.alertStatus==='OUT_OF_STOCK'?'out-of-stock-row':''
const filteredStocks=computed(()=>stocks.value.filter((row:any)=>{const q=appliedQuery.value;const keyword=q.keyword.trim().toLowerCase();return(!keyword||String(row.materialCode).toLowerCase().includes(keyword)||String(row.materialName).toLowerCase().includes(keyword))&&(!q.batchNo||String(row.batchNo).toLowerCase().includes(q.batchNo.toLowerCase()))&&(!q.warehouse||String(row.warehouse).toLowerCase().includes(q.warehouse.toLowerCase()))&&(!q.location||String(row.location||'').toLowerCase().includes(q.location.toLowerCase()))&&(!q.alertStatus||row.alertStatus===q.alertStatus)}))
const filteredTxns=computed(()=>txns.value.filter((row:any)=>{const q=appliedTxnQuery.value;const keyword=q.keyword.trim().toLowerCase();return(!keyword||String(row.txnNo||'').toLowerCase().includes(keyword)||String(row.bizNo||'').toLowerCase().includes(keyword)||String(row.materialName||'').toLowerCase().includes(keyword))&&(!q.bizType||row.bizType===q.bizType)&&(!q.batchNo||String(row.batchNo||'').toLowerCase().includes(q.batchNo.toLowerCase()))&&(!q.direction||row.direction===q.direction)}))
function applyQuery(){appliedQuery.value={...query};queryVisible.value=false;ElMessage.success(`查询完成，共 ${filteredStocks.value.length} 条记录`)}
function resetQuery(){Object.assign(query,{keyword:'',batchNo:'',warehouse:'',location:'',alertStatus:''});appliedQuery.value={...query};ElMessage.success('查询条件已重置，已恢复全部记录')}
function applyTxnQuery(){appliedTxnQuery.value={...txnQuery};txnQueryVisible.value=false;ElMessage.success(`查询完成，共 ${filteredTxns.value.length} 条流水`)}
function resetTxnQuery(){Object.assign(txnQuery,{keyword:'',bizType:'',batchNo:'',direction:''});appliedTxnQuery.value={...txnQuery};ElMessage.success('查询条件已重置，已恢复全部流水')}
const htmlEscape=(value:any)=>String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')
function stockTableHtml(){const body=filteredStocks.value.map((r:any)=>`<tr><td>${htmlEscape(r.materialCode)}</td><td>${htmlEscape(r.materialName)}</td><td>${htmlEscape(r.batchNo)}</td><td>${htmlEscape(r.warehouse)}</td><td>${htmlEscape(r.location)}</td><td>${htmlEscape(r.quantity)} ${htmlEscape(r.unit)}</td><td>${htmlEscape(r.expiryDate)}</td><td>${htmlEscape(alertName(r.alertStatus))}</td></tr>`).join('');return `<table border="1"><thead><tr><th>编码</th><th>物料名称</th><th>批次</th><th>仓库</th><th>库位</th><th>数量</th><th>有效期</th><th>预警</th></tr></thead><tbody>${body}</tbody></table>`}
function exportStocks(){if(!filteredStocks.value.length){ElMessage.warning('当前没有可导出的查询结果');return}const html=`<html><head><meta charset="UTF-8"></head><body>${stockTableHtml()}</body></html>`;const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`物料信息库_${new Date().toISOString().slice(0,10)}.xls`;link.click();URL.revokeObjectURL(url);ElMessage.success('查询结果已导出')}
function exportApprovedPurchases(){const approved=purchases.value.filter((row:any)=>row.status==='APPROVED');if(!approved.length){ElMessage.warning('当前没有状态为“已通过”的采购申请');return}const rows=approved.map((r:any)=>`<tr><td>${htmlEscape(r.requestNo)}</td><td>${htmlEscape(r.materialCode)}</td><td>${htmlEscape(r.materialName)}</td><td>${htmlEscape(r.quantity)}</td><td>${htmlEscape(r.expectedDate)}</td><td>${htmlEscape(r.purpose)}</td><td>已通过</td></tr>`).join('');const table=`<table border="1"><thead><tr><th>申请编号</th><th>物料编码</th><th>物料名称</th><th>数量</th><th>期望日期</th><th>用途</th><th>状态</th></tr></thead><tbody>${rows}</tbody></table>`;const html=`<html><head><meta charset="UTF-8"></head><body>${table}</body></html>`;const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`已通过采购申请_${new Date().toISOString().slice(0,10)}.xls`;link.click();URL.revokeObjectURL(url);ElMessage.success(`已导出 ${approved.length} 条已通过采购申请`)}
function printStocks(){if(!filteredStocks.value.length){ElMessage.warning('当前没有可打印的查询结果');return}const win=window.open('','_blank','width=1100,height=760');if(!win){ElMessage.warning('浏览器阻止了打印窗口，请允许弹出窗口');return}win.document.write(`<html><head><meta charset="UTF-8"><title>物料信息库</title><style>body{font-family:Arial,"Microsoft YaHei";padding:24px}h1{text-align:center;font-size:22px}p{text-align:right;color:#666}table{width:100%;border-collapse:collapse}th,td{padding:8px;border:1px solid #999;text-align:left}th{background:#eef4ff}</style></head><body><h1>物料信息库</h1><p>打印时间：${new Date().toLocaleString()}</p>${stockTableHtml()}</body></html>`);win.document.close();win.focus();win.print()}
function txnTableHtml(){const body=filteredTxns.value.map((r:any)=>`<tr><td>${htmlEscape(r.txnNo)}</td><td>${htmlEscape(bizTypeName(r.bizType))}</td><td>${htmlEscape(r.bizNo)}</td><td>${htmlEscape(r.materialName)}</td><td>${htmlEscape(r.batchNo)}</td><td>${htmlEscape(directionName(r.direction))}</td><td>${htmlEscape(r.quantity)}</td><td>${htmlEscape(r.unitCost)}</td><td>${htmlEscape(r.purpose)}</td><td>${htmlEscape(r.occurredAt)}</td></tr>`).join('');return `<table border="1"><thead><tr><th>流水号</th><th>业务类型</th><th>业务编号</th><th>物料</th><th>批次</th><th>方向</th><th>数量</th><th>单位成本</th><th>用途</th><th>发生时间</th></tr></thead><tbody>${body}</tbody></table>`}
function exportTxns(){if(!filteredTxns.value.length){ElMessage.warning('当前没有可导出的流水记录');return}const html=`<html><head><meta charset="UTF-8"></head><body>${txnTableHtml()}</body></html>`;const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`库存流水_${new Date().toISOString().slice(0,10)}.xls`;link.click();URL.revokeObjectURL(url);ElMessage.success('库存流水已导出')}
function printTxns(){if(!filteredTxns.value.length){ElMessage.warning('当前没有可打印的流水记录');return}const win=window.open('','_blank','width=1200,height=760');if(!win){ElMessage.warning('浏览器阻止了打印窗口，请允许弹出窗口');return}win.document.write(`<html><head><meta charset="UTF-8"><title>库存流水</title><style>body{font-family:Arial,"Microsoft YaHei";padding:24px}h1{text-align:center;font-size:22px}p{text-align:right;color:#666}table{width:100%;border-collapse:collapse}th,td{padding:7px;border:1px solid #999;text-align:left}th{background:#eef4ff}</style></head><body><h1>库存流水</h1><p>打印时间：${new Date().toLocaleString()}</p>${txnTableHtml()}</body></html>`);win.document.close();win.focus();win.print()}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p>INVENTORY</p><h1>物料管理</h1></div></div>
<el-tabs v-model="tab"><el-tab-pane label="物料档案" name="materials"><div class="tab-action-bar"><el-button class="material-create-button" type="primary" @click="newMaterial">新增物料</el-button></div><div class="content-card"><el-table :data="materials"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column prop="category" label="分类"/><el-table-column prop="specification" label="规格"/><el-table-column prop="baseUnit" label="单位"/><el-table-column label="危险属性"><template #default="s"><el-tag :type="s.row.hazardType==='NORMAL'?'info':'warning'">{{hazardName(s.row.hazardType)}}</el-tag></template></el-table-column><el-table-column prop="minStock" label="最低库存"/><el-table-column label="编辑" width="190" fixed="right"><template #default="s"><div class="material-actions"><el-button class="material-action material-edit-action" type="primary" @click="editMaterial(s.row)">修改</el-button><el-tooltip :content="s.row.deleteDisabledReason||'该记录当前不能删除'" placement="top" :disabled="s.row.deletable"><span class="material-delete-wrapper"><el-button class="material-action material-delete-action" type="danger" :disabled="!s.row.deletable" @click="removeMaterial(s.row)">删除</el-button></span></el-tooltip></div></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="采购与入库" name="purchase"><div class="tab-action-bar purchase-action-bar"><el-button class="purchase-create-button" type="primary" @click="purchaseVisible=true">采购申请</el-button><el-button class="purchase-export-button" type="success" @click="exportApprovedPurchases">导出采购清单</el-button></div><div class="content-card"><el-table :data="purchases"><el-table-column prop="requestNo" label="申请编号"/><el-table-column prop="materialCode" label="物料编码"/><el-table-column prop="materialName" label="物料"/><el-table-column prop="quantity" label="数量"/><el-table-column prop="expectedDate" label="期望日期"/><el-table-column prop="purpose" label="用途"/><el-table-column label="状态"><template #default="s"><el-tag :type="purchaseStatusType(s.row.status) as any">{{purchaseStatusName(s.row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="225" fixed="right"><template #default="s"><div class="purchase-actions"><template v-if="s.row.status==='DRAFT'"><el-button class="purchase-action purchase-submit-action" type="primary" @click="submit(s.row)">提交</el-button><el-button class="purchase-action purchase-reject-action" type="danger" @click="removePurchase(s.row)">删除</el-button></template><template v-if="s.row.status==='SUBMITTED'"><el-button class="purchase-action purchase-approve-action" type="success" @click="review(s.row,true)">申请通过</el-button><el-button class="purchase-action purchase-reject-action" type="danger" @click="review(s.row,false)">退回</el-button></template><el-button v-if="s.row.status==='APPROVED'" class="purchase-action purchase-receipt-action" type="warning" @click="openPurchaseReceipt(s.row)">验收入库</el-button><template v-if="s.row.status==='RECEIPT_REVIEW'"><el-button class="purchase-action purchase-approve-action" type="success" @click="reviewReceipt(s.row,true)">入库通过</el-button><el-button class="purchase-action purchase-reject-action" type="danger" @click="reviewReceipt(s.row,false)">退回</el-button></template></div></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="领用与出库" name="issues"><div class="tab-action-bar issue-action-bar"><el-button class="issue-create-button" type="primary" @click="issueVisible=true">出库申请</el-button></div><div class="content-card"><el-table :data="issues"><el-table-column prop="requestNo" label="申请编号"/><el-table-column prop="materialCode" label="物料编码"/><el-table-column prop="materialName" label="物料"/><el-table-column prop="batchNo" label="批次"/><el-table-column label="出库数量"><template #default="s">{{s.row.quantity}} {{s.row.unit}}</template></el-table-column><el-table-column prop="purpose" label="用途"/><el-table-column label="状态" width="110"><template #default="s"><el-tag :type="issueStatusType(s.row.status) as any">{{issueStatusName(s.row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="225" fixed="right"><template #default="s"><div class="issue-actions"><template v-if="s.row.status==='DRAFT'"><el-button class="issue-action issue-submit-action" type="primary" @click="submitIssue(s.row)">提交</el-button><el-button class="issue-action issue-delete-action" type="danger" @click="removeIssue(s.row)">删除</el-button></template><template v-if="s.row.status==='SUBMITTED'"><el-button class="issue-action issue-approve-action" type="success" @click="reviewIssue(s.row,true)">申请通过</el-button><el-button class="issue-action issue-delete-action" type="danger" @click="reviewIssue(s.row,false)">退回</el-button></template></div></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="物料信息库" name="stocks"><div class="tab-action-bar stock-action-bar"><div class="stock-query-actions"><el-button type="primary" @click="queryVisible=true">查询</el-button><el-button @click="exportStocks">导出</el-button><el-button @click="printStocks">打印</el-button><el-button @click="resetQuery">重置</el-button></div></div><div class="content-card"><el-table v-loading="loading" :data="filteredStocks" :row-class-name="stockRowClassName"><el-table-column prop="materialCode" label="编码"/><el-table-column prop="materialName" label="物料名称"/><el-table-column prop="batchNo" label="批次"/><el-table-column prop="warehouse" label="仓库"/><el-table-column prop="location" label="库位"/><el-table-column label="数量"><template #default="s">{{s.row.quantity}} {{s.row.unit}}</template></el-table-column><el-table-column prop="expiryDate" label="有效期"/><el-table-column label="预警"><template #default="s"><el-tag :type="s.row.alertStatus==='NORMAL'?'success':s.row.alertStatus==='EXPIRING'?'warning':'danger'">{{alertName(s.row.alertStatus)}}</el-tag></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="库存流水" name="txns"><div class="tab-action-bar stock-action-bar"><div class="stock-query-actions"><el-button type="primary" @click="txnQueryVisible=true">查询</el-button><el-button @click="exportTxns">导出</el-button><el-button @click="printTxns">打印</el-button><el-button @click="resetTxnQuery">重置</el-button></div></div><div class="content-card"><el-table :data="filteredTxns"><el-table-column prop="txnNo" label="流水号"/><el-table-column label="业务类型"><template #default="s"><el-tag>{{bizTypeName(s.row.bizType)}}</el-tag></template></el-table-column><el-table-column prop="materialName" label="物料"/><el-table-column prop="batchNo" label="批次"/><el-table-column label="方向"><template #default="s"><el-tag :type="s.row.direction==='IN'?'success':'warning'">{{directionName(s.row.direction)}}</el-tag></template></el-table-column><el-table-column prop="quantity" label="数量"/><el-table-column prop="unitCost" label="单位成本"/><el-table-column prop="occurredAt" label="发生时间"/></el-table></div></el-tab-pane></el-tabs>
<el-dialog v-model="queryVisible" title="查询物料信息库" width="580px"><el-form label-width="90px"><el-form-item label="编码/名称"><el-input v-model="query.keyword" clearable placeholder="请输入物料编码或名称"/></el-form-item><el-form-item label="批次"><el-input v-model="query.batchNo" clearable/></el-form-item><el-form-item label="仓库"><el-input v-model="query.warehouse" clearable/></el-form-item><el-form-item label="库位"><el-input v-model="query.location" clearable/></el-form-item><el-form-item label="预警状态"><el-select v-model="query.alertStatus" clearable placeholder="全部状态"><el-option label="正常" value="NORMAL"/><el-option label="低库存" value="LOW"/><el-option label="无库存" value="OUT_OF_STOCK"/><el-option label="临期" value="EXPIRING"/><el-option label="已过期" value="EXPIRED"/></el-select></el-form-item></el-form><template #footer><el-button @click="resetQuery">重置</el-button><el-button @click="queryVisible=false">取消</el-button><el-button type="primary" @click="applyQuery">查询</el-button></template></el-dialog>
<el-dialog v-model="txnQueryVisible" title="查询库存流水" width="580px"><el-form label-width="90px"><el-form-item label="关键词"><el-input v-model="txnQuery.keyword" clearable placeholder="流水号、业务编号或物料名称"/></el-form-item><el-form-item label="业务类型"><el-select v-model="txnQuery.bizType" clearable placeholder="全部类型"><el-option label="验收入库" value="RECEIPT"/><el-option label="领用出库" value="ISSUE"/><el-option label="退库" value="RETURN"/><el-option label="调拨" value="TRANSFER"/><el-option label="盘点调整" value="STOCKTAKE"/><el-option label="报损处置" value="DISPOSAL"/></el-select></el-form-item><el-form-item label="批次"><el-input v-model="txnQuery.batchNo" clearable/></el-form-item><el-form-item label="方向"><el-select v-model="txnQuery.direction" clearable placeholder="全部方向"><el-option label="入库" value="IN"/><el-option label="出库" value="OUT"/></el-select></el-form-item></el-form><template #footer><el-button @click="resetTxnQuery">重置</el-button><el-button @click="txnQueryVisible=false">取消</el-button><el-button type="primary" @click="applyTxnQuery">查询</el-button></template></el-dialog>
<el-dialog v-model="materialVisible" :title="materialEditingId?'修改物料档案':'新增物料档案'" width="550px"><el-form label-width="90px"><el-form-item label="物料编码"><el-input v-model="material.code"/></el-form-item><el-form-item label="物料名称"><el-input v-model="material.name"/></el-form-item><el-form-item label="分类"><el-select v-model="material.category"><el-option v-for="x in ['试剂','耗材','标准物质','标准试剂','危险品']" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="规格"><el-input v-model="material.specification"/></el-form-item><el-form-item label="单位"><el-input v-model="material.baseUnit"/></el-form-item><el-form-item label="危险属性"><el-select v-model="material.hazardType"><el-option label="普通" value="NORMAL"/><el-option label="危化品" value="HAZARDOUS"/><el-option label="易制毒" value="PRECURSOR"/><el-option label="易制爆" value="EXPLOSIVE"/></el-select></el-form-item><el-form-item label="最低库存"><el-input-number v-model="material.minStock" :min="0"/></el-form-item></el-form><template #footer><el-button @click="materialVisible=false">取消</el-button><el-button type="primary" @click="saveMaterial">保存</el-button></template></el-dialog>
<el-dialog v-model="purchaseVisible" title="采购申请" width="520px"><el-form label-width="90px"><el-form-item label="物料"><el-select v-model="purchase.materialId" filterable><el-option v-for="m in materials" :key="m.id" :label="m.name" :value="m.id"/></el-select></el-form-item><el-form-item label="数量"><el-input-number v-model="purchase.quantity" :min="0.000001"/></el-form-item><el-form-item label="期望日期"><el-date-picker v-model="purchase.expectedDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="用途"><el-input v-model="purchase.purpose" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="purchaseVisible=false">取消</el-button><el-button type="primary" @click="savePurchase">保存</el-button></template></el-dialog>
<el-dialog v-model="receiptVisible" title="验收入库" width="620px"><el-form label-width="90px"><el-form-item label="采购单号"><el-input v-model="receipt.bizNo" disabled/></el-form-item><el-form-item label="物料"><el-select v-model="receipt.materialId" disabled><el-option v-for="m in materials" :key="m.id" :label="`${m.code} / ${m.name}`" :value="m.id"/></el-select></el-form-item><el-form-item label="供应商"><el-select v-model="receipt.supplierId" clearable><el-option v-for="s in suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="批次号"><el-input v-model="receipt.batchNo"/></el-form-item><el-form-item label="仓库/库位"><div style="display:flex;gap:8px"><el-input v-model="receipt.warehouse"/><el-input v-model="receipt.location"/></div></el-form-item><el-form-item label="验收数量"><el-input-number v-model="receipt.quantity" :min="0.000001"/></el-form-item><el-form-item label="单位价格"><el-input-number v-model="receipt.unitCost" :min="0" :precision="2"/></el-form-item><el-form-item label="生产日期"><el-date-picker v-model="receipt.productionDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="有效期"><el-date-picker v-model="receipt.expiryDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="用途"><el-input v-model="receipt.purpose" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="receiptVisible=false">取消</el-button><el-button type="primary" @click="saveReceipt">提交审核</el-button></template></el-dialog>
<el-dialog v-model="issueVisible" title="出库申请" width="520px"><el-form label-width="90px"><el-form-item label="库存批次"><el-select v-model="issue.batchId" filterable @change="validateIssueQuantity"><el-option v-for="s in stocks.filter(x=>Number(x.quantity)>0)" :key="s.batchId" :label="`${s.materialName} / ${s.batchNo} / 余${s.quantity}`" :value="s.batchId"/></el-select></el-form-item><el-form-item label="数量"><el-input-number v-model="issue.quantity" :min="0.000001" @change="onIssueQuantityChange"/><span v-if="selectedIssueStock" class="issue-stock-hint">当前库存：{{selectedIssueStock.quantity}} {{selectedIssueStock.unit}}</span></el-form-item><el-form-item label="用途"><el-input v-model="issue.purpose" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="issueVisible=false">取消</el-button><el-button type="primary" @click="saveIssue">申请出库</el-button></template></el-dialog></section></template>

<style scoped>
.tab-action-bar{display:flex;justify-content:flex-start;align-items:center;gap:10px;margin-bottom:12px}.stock-action-bar{justify-content:flex-end}.stock-query-actions{display:flex;align-items:center;gap:3px}.stock-query-actions :deep(.el-button){height:38px;margin-left:0}.stock-query-actions :deep(.el-button:first-child){margin-right:9px}.issue-create-button{height:38px;min-width:104px;font-size:14px;font-weight:700}
.issue-stock-hint{margin-left:12px;color:#909399;font-size:13px}
.content-card :deep(.el-table .out-of-stock-row td.el-table__cell){background:#eef0f3!important;color:#8a9099}.content-card :deep(.el-table .out-of-stock-row:hover td.el-table__cell){background:#e5e7eb!important}
.purchase-action-bar{justify-content:space-between}.material-create-button,.purchase-create-button,.purchase-export-button{height:38px;min-width:104px;font-size:14px;font-weight:700}.purchase-export-button{border:0;background:linear-gradient(110deg,#0fa36f,#25bd8a);color:#fff}.material-actions,.purchase-actions,.issue-actions{display:flex;align-items:center;gap:5px}.material-actions :deep(.el-button+.el-button),.purchase-actions :deep(.el-button+.el-button),.issue-actions :deep(.el-button+.el-button){margin-left:0}.material-delete-wrapper{display:inline-flex}.material-action,.purchase-action,.issue-action{min-width:76px;height:36px;border:0;border-radius:8px;font-size:14px;font-weight:800;color:#fff}.material-edit-action,.purchase-submit-action,.issue-submit-action{background:linear-gradient(110deg,#347df0,#5264dc)}.material-delete-action,.purchase-reject-action,.issue-delete-action{background:linear-gradient(110deg,#f05c68,#d9364e)}.purchase-approve-action,.issue-approve-action{background:linear-gradient(110deg,#0fa36f,#25bd8a)}.purchase-receipt-action{min-width:104px;background:linear-gradient(110deg,#f2a52b,#e67b18)}.material-delete-action.is-disabled{background:#c5c9d1!important;border-color:#c5c9d1!important;color:#fff!important;cursor:not-allowed}
</style>
